export function icon(name,className=''){return `<svg class="icon ${className}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||''}"/></svg>`;}
export const NAV_ITEMS=[['prepare','rod','Đi câu'],['rig','bag','Đồ nghề'],['learn','book','Học câu'],['journal','collection','Sổ cá'],['shop','shop','Chợ bến']];
export function rankFor(catches){
 const ranks=[[0,'Tân thủ'],[5,'Cần thủ ao làng'],[15,'Tay câu vững'],[30,'Lão làng'],[60,'Đại lão câu cá']];
 const i=ranks.findLastIndex(([n])=>catches>=n),start=ranks[i][0],next=ranks[i+1]?.[0];
 return {name:ranks[i][1],count:catches-start,max:next?next-start:1,label:next?`${catches} / ${next} cá`:`${catches} cá · Bậc cao nhất`,complete:!next};
}
export function avatarArt(){return `<svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="30" fill="#284f40"/><path d="M14 62q0-19 18-19t18 19" fill="#a5956b"/><path d="M23 25h18v12q-2 13-9 13t-9-13" fill="#e8bd83"/><path d="M11 28 32 5l21 23q-22 9-42 0" fill="#e3bd71" stroke="#836335" stroke-width="2"/><path d="M21 27 32 8l11 19M11 28h42" fill="none" stroke="#b48b47" stroke-width="2"/><path d="M27 36h1m8 0h1M28 43q4 3 8 0" stroke="#674e31" stroke-width="2" stroke-linecap="round"/></svg>`;}
function fishFallbackArt(f){
 if(f?.group&&f.group!=='fish')return creatureFallbackArt(f);
 const color=f?.color||'#71847c',shape=f?.shape||'carp',id=f?.id||'unknown';
 const [rx,ry]=({catfish:[69,18],long:[71,15],knife:[67,23],round:[48,29],grouper:[58,26],carp:[54,24]})[shape],head=98+rx-13;
 const body=shape==='knife'?'<path d="M29 40q33-47 111-15 21 9 24 19-22 36-113 16Z"/>':`<ellipse cx="98" cy="44" rx="${rx}" ry="${ry}"/>`;
 const pattern=f?.pattern==='stripes'?`<path d="M68 19l-4 45M84 16l-3 52M100 17l-2 53M116 19l-1 44" stroke="#fff" stroke-opacity=".3" stroke-width="4"/>`:f?.pattern==='spots'?Array.from({length:9},(_,i)=>`<circle cx="${53+(i%5)*19}" cy="${34+Math.floor(i/5)*16}" r="${id==='fish_24'?5:2.8}" fill="${id==='fish_24'?'#263d3b':'#d6a578'}" opacity=".65"/>`).join(''):`<path d="M63 31q10 15 0 26m16-29q10 16 0 31m16-31q10 16 0 31m16-29q10 14 0 26" stroke="#fff" stroke-opacity=".15" fill="none" stroke-width="1.5"/>`;
 const whiskers=shape==='catfish'?`<path d="M${head+8} 42q19-18 32-12M${head+8} 49q18 2 25 19" fill="none" stroke="${color}" stroke-width="2"/>`:'';
 const fin=shape==='round'?'<path d="M64 26 78 7l14 7 15-11 21 20M76 63l17 19 22-18"/>':'<path d="M68 28 93 10 122 26M82 61l21 16 17-19"/>';
 return `<svg viewBox="0 0 200 88" aria-hidden="true"><g fill="${color}"><path d="M${98-rx+8} 44 10 23 13 65Z"/>${fin}${body}</g>${pattern}<path d="M${98-rx+12} 50q48 18 ${rx*2-25} -3" fill="none" stroke="#fff" stroke-opacity=".25" stroke-width="3"/><path d="M${head-7} 30q-9 12 0 25" stroke="#183D37" fill="none" opacity=".35"/><circle cx="${head+1}" cy="36" r="3.5" fill="#fff9eb"/><circle cx="${head+2}" cy="36" r="1.8" fill="#183D37"/>${whiskers}</svg>`;
}
