export function fishArt(f){
 if(!f)return fishFallbackArt(f);
 const paths=speciesAssetPaths(f).filter(path=>FISH_IMAGE_FILES[path.split('/').at(-1)]);
 const fallback=fishFallbackArt(f);
 return paths.length?`<span class="fish-visual"><img src="${paths[0]}" alt="${esc(f.name)}" loading="lazy" decoding="async" data-fish-image="${f.id}" data-fish-paths="${esc(JSON.stringify(paths))}" data-fish-index="0">${fallback}</span>`:fallback;
}
export function specimenSummary(f,weight){
 const length=estimatedSpecimenLength(f,weight),score=specimenStrength(f,weight).powerScore;
 return `${f.size?.measure||'Chiều dài'} ~${length} cm · sức kéo ${score}/10`;
}
const weightLabel=v=>v<1?`${Math.round(v*1000)} g`:`${new Intl.NumberFormat('vi-VN',{maximumFractionDigits:2}).format(v)} kg`;
const weightRange=(a,b)=>`${weightLabel(a)}–${weightLabel(b)}`;
export function speciesDetailHTML(f){
 const s=f.size,relative=specimenStrength(f,(s.common[0]+s.common[1])/2).relativeScore;
 return `<div class="species-detail-art">${fishArt(f)}</div><p class="species-scientific"><i>${esc(f.scientificName)}</i>${f.taxonomyStatus==='representative'?' · Loài đại diện theo tên địa phương':''}</p><p><b>Nhận dạng:</b> ${esc(f.recognition)}</p><p><b>Nơi sống:</b> ${esc(f.habitat)}</p><p><b>Trong game:</b> ${f.maps.map(id=>esc(getMap(id).name)).join(' · ')}</p><p><b>Thức ăn:</b> ${esc(f.diet)}</p><p><b>Mồi ưu tiên:</b> ${f.baits.map((id,i)=>esc(getBait(id).name)+(i===0?' ★':'')).join(' · ')}<br><b>Cách câu:</b> ${f.tech.map(t=>esc(TECHNIQUES[t].label)).join(' / ')} · ${f.depth==='bottom'?'Sát đáy':f.depth==='surface'?'Sát mặt, mép nước':f.depth==='cover'?'Gần chỗ trú':'Tầng giữa'}</p><p><b>Kiểu kéo:</b> ${esc(f.fight.label)} · Sức tương đối cùng cân nặng ${relative}/10.</p><div class="species-table-scroll"><table class="species-table"><caption>Cỡ và sức kéo trong mô phỏng</caption><thead><tr><th>Cỡ</th><th>Cân nặng</th><th>${esc(s.measure)} ước tính</th><th>Sức kéo</th></tr></thead><tbody>${speciesSizeBands(f).map(b=>`<tr><th>${b.label}</th><td>${weightRange(b.min,b.max)}</td><td>${estimatedSpecimenLength(f,b.min)}–${estimatedSpecimenLength(f,b.max)} cm</td><td>${specimenStrength(f,b.min).powerScore}–${specimenStrength(f,b.max).powerScore}/10</td></tr>`).join('')}</tbody></table></div><p class="hint-note">Cỡ thường gặp trong mô phỏng: ${weightRange(...s.common)}; trung điểm ${weightLabel((s.common[0]+s.common[1])/2)}. Các khoảng cỡ, chiều dài ước tính, mồi ưu tiên và điểm sức kéo là thông số thiết kế game, không phải trung bình khảo sát hay lực đo ngoài tự nhiên.</p>${f.referenceSize.maxCm||f.referenceSize.maxKg?`<p class="hint-note">Tham chiếu công bố${f.referenceSize.maxCm?`: dài tối đa ${f.referenceSize.maxCm} cm (${esc(f.referenceSize.measure)})`:''}${f.referenceSize.maxKg?`; khối lượng tối đa công bố ${weightLabel(f.referenceSize.maxKg)}`:''}. Đây không phải kỷ lục riêng tại Việt Nam. TL: dài toàn thân; SL: dài chuẩn không tính vây đuôi; FL: dài đến chạc đuôi.</p>`:''}<p class="hint-note">${esc(f.notes)}</p><p class="species-sources">Nguồn nhận dạng và sinh học: ${f.sources.map(source=>`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.label)}</a>`).join(' · ')} · Đối chiếu ${f.researchDate}</p>`;
}
